"""18 egna uppgifter inspirerade av lärarens exempel; individuella lösningar."""
import json,math,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def p(s):return '<p>'+s+'</p>'
def m(s):return r'\('+s+r'\)'
def eq(s):return '<div class="facit-matte">'+r'\['+s+r'\]'+'</div>'
def sol(steps,answer):return '<div class="facit-v2 facit-stegvis"><ol class="facit-steglista" role="list">'+''.join('<li>'+v+'</li>' for v in steps)+'</ol><p class="facit-svar"><strong>Svar: '+answer+'</strong></p></div>'
def text(x,y,s,size=18):return f'<text x="{x}" y="{y}" text-anchor="middle" font-family="Arial,sans-serif" font-size="{size}" fill="#173548">{html.escape(str(s))}</text>'
def svg(title,body,height=200):return '<span class="fig"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 '+str(height)+'" style="width:100%;max-width:500px" role="img" aria-label="'+html.escape(title)+'"><title>'+html.escape(title)+'</title><rect width="500" height="'+str(height)+'" fill="white" rx="10"/>'+body+'</svg></span>'
def books():
 body='<path d="M25 160H475" stroke="#173548" stroke-width="5"/>'
 for i,label in enumerate('ABCDEFG'):
  body+=f'<rect x="{40+i*61}" y="50" width="42" height="108" rx="3" fill="#e6eff9" stroke="#2463a2" stroke-width="2"/>'+text(61+i*61,112,label)
 return svg('Sju olika böcker märkta A till G.',body)
def urn():
 body='<path d="M55 45H170L188 145Q112 180 37 145Z" fill="#e6eff9" stroke="#2463a2" stroke-width="2"/>'+text(112,100,'1–40',23)
 body+=text(350,38,'De fyra valda talen i storleksordning',15)
 for i,label in enumerate(['?','8','?','?']):body+=f'<rect x="{230+i*62}" y="70" width="48" height="50" rx="5" fill="#fff" stroke="#173548" stroke-width="2"/>'+text(254+i*62,102,label,22)
 return svg('En urna med lappar 1 till 40. Fyra valda tal sorteras; det andra är 8.',body)
def clock():
 body='<rect x="110" y="25" width="280" height="92" rx="12" fill="#e6eff9" stroke="#2463a2" stroke-width="2"/>'+text(250,84,'17:00',42)+text(250,154,'Vad visar klockan efter 7¹²³ timmar?',19)
 return svg('En digital klocka visar 17:00.',body,190)
def area():
 X=lambda x:65+350*x/(math.pi/2);Y=lambda y:250-200*y
 pts=[(math.pi/2*i/100) for i in range(101)];coords=' '.join(f'{X(x):.2f},{Y(x*math.cos(x)):.2f}' for x in pts)
 body=f'<polygon points="65,250 {coords} 415,250" fill="#d4e8f7"/>'+f'<polyline points="{coords}" fill="none" stroke="#096c9a" stroke-width="3"/>'
 body+='<path d="M65 35V250H455" fill="none" stroke="#173548" stroke-width="2"/>'+text(65,278,'0')+text(415,278,'π/2')+text(456,278,'x')+text(48,25,'y')+text(245,65,'y = x cos x')
 return svg('Området under y=x cos x mellan x=0 och x=pi/2.',body,300)
TASKS=[]
def add(id,omr,level,t,answer,steps,final,hint,fmt='numeriskt',family=None,fig='',calc=True,skills=None):
 TASKS.append(dict(id=id,kap=int(id.split('.')[0]),omr=omr,niva='E' if level<=2 else 'C' if level<=4 else 'A',poang='2/0/0' if level<=2 else '0/2/0' if level<=4 else '0/0/2',traningsniva=level,arbetsinsats=1 if level<=2 else 2 if level<=4 else 3,familj=family or {'permutationer':'Fakulteter och ordningar','kombinationer':'Urval med villkor','kongruens':'Rester och perioder','partiell_integration':'Partiell integration'}[omr],formaga=skills or ['procedur','begrepp'],miniräknare=calc,geogebra=False,spel=True,självrättning=True,t=t+fig,s=sol(steps,final),ledtrad=p(hint),rättSvar=answer,svarstyp='text' if fmt in ['uttryck','primitiva'] else 'numeriskt',svarFormat=fmt,tolerans=0 if fmt in ['numeriskt','antal_satt'] else None))
add('1.802','kombinationer',2,p('En förening har tio ledamöter. Sju av dem ska ingå i en arbetsgrupp, utan några särskilda roller. Hur många olika grupper kan bildas?'),120,[p('Det spelar ingen roll i vilken ordning personerna väljs. Välj sju av tio.')+eq(r'\binom{10}{7}=\binom{10}{3}')+eq(r'=\frac{10\cdot9\cdot8}{3\cdot2\cdot1}=120')],'120 grupper.','Du kan också välja vilka tre som inte ska vara med.',fmt='antal_satt')
add('1.803','permutationer',3,p('Sju olika böcker ska stå på en rad. Böckerna A och B måste stå intill varandra, men får byta plats med varandra. Hur många ordningar är möjliga?'),1440,[p('Räkna först A och B som ett block. Blocket och de fem andra böckerna är sex enheter som kan ordnas på 6! sätt.'),p('I blocket kan A och B stå i två ordningar.')+eq(r'2\cdot6!=1440')],'1 440 ordningar.','Behandla först de två böckerna som ett block.',fmt='antal_satt',fig=books())
add('1.804','permutationer',2,p('n är ett positivt heltal. Skriv kvoten utan fakultetstecken.')+eq(r'\frac{(n+2)!}{n!}'),'(n+1)*(n+2)',[p('Skriv ut de två största faktorerna i täljaren.')+eq(r'(n+2)!=(n+2)(n+1)n!'),p('Faktorn n! kan förkortas bort.')],m('(n+2)(n+1)')+'.','Hur många faktorer återstår när n! förkortas bort?',fmt='uttryck',calc=False)
add('1.805','permutationer',3,p('n är ett heltal och n ≥ 3. Vilket uttryck ska stå i rutan?')+eq(r'(n+1)!-3n!=n!\cdot\boxed{\phantom{xxxx}}'),'n-2',[p('Skriv (n+1)! som (n+1)n! och bryt ut n!.')+eq(r'=n!((n+1)-3)'),p('Faktorn i parentesen är n−2.')],m('n-2')+'.','Båda termerna innehåller faktorn n!.',fmt='uttryck',calc=False)
add('1.806','permutationer',4,p('n är ett positivt heltal. Förenkla till ett uttryck utan fakultetstecken.')+eq(r'\frac{(n+2)!+(n+1)!}{n!}'),'(n+1)*(n+3)',[p('Dela upp kvoten och förkorta n! i varje term.')+eq(r'=(n+2)(n+1)+(n+1)'),p('Bryt ut den gemensamma faktorn n+1.')+eq(r'=(n+1)((n+2)+1)')],m('(n+1)(n+3)')+'.','Förkorta i varje term innan du förenklar summan.',fmt='uttryck',calc=False)
add('1.807','kombinationer',4,p('En urna innehåller 40 lappar, numrerade från 1 till 40. Fyra olika lappar väljs utan återläggning. Dragordningen spelar ingen roll. I hur många urval är det näst minsta talet 8?'),3472,[p('Lappen 8 måste vara med. Exakt en lapp ska ha ett lägre tal: den kan väljas bland 1–7, alltså på 7 sätt.'),p('De två övriga lapparna ska väljas bland 9–40. Det är 32 lappar, och deras ordning spelar ingen roll.')+eq(r'7\cdot\binom{32}{2}=7\cdot496=3472')],'3 472 urval.','Hur många valda tal måste vara mindre respektive större än 8?',fmt='antal_satt',fig=urn(),skills=['problemlösning','begrepp'])
add('1.808','permutationer',2,p('n olika fotografier kan ordnas på en rad på exakt 120 sätt. Alla fotografier används. Hur många fotografier finns det?'),5,[p('Antalet ordningar av n olika föremål är n!. Därför ska n! = 120.'),p('Eftersom 4! = 24 och 5! = 120 får vi n = 5.')],'5 fotografier.','Vilken fakultet är lika med 120?',fmt='antal_satt')
add('2.720','kongruens',1,p('Bestäm resten r vid division av 47 med 6.')+eq(r'47\equiv r\pmod6,\qquad 0\le r<6'),5,[p('47 = 7·6+5. Resten är därför 5.')],'r = 5.','Hitta närmaste multipel av 6 som är mindre än 47.')
add('2.721','kongruens',2,p('Bestäm heltalet a som uppfyller båda kongruenserna och ligger i intervallet 20 ≤ a ≤ 50.')+eq(r'a\equiv2\pmod5')+eq(r'a\equiv4\pmod7'),32,[p('Den första kongruensen ger kandidaterna 22, 27, 32, 37, 42 och 47 i intervallet.'),p('Vid division med 7 ger de resterna 1, 6, 4, 2, 0 och 5. Bara 32 ger resten 4.')],'a = 32.','Lista först talen i intervallet som uppfyller en av kongruenserna.')
add('2.722','kongruens',1,p('Vilket är det minsta positiva heltal som kan läggas till 79 för att summan ska vara kongruent med 0 modulo 13?'),12,[p('Kongruent med 0 modulo 13 betyder delbart med 13. Nästa multipel efter 79 är 7·13 = 91.'),p('Skillnaden är 91−79 = 12.')],'12.','Vad innebär det att resten är 0?')
add('2.723','kongruens',3,p('Klockan är 17.00. Vad visar klockan efter '+m('7^{123}')+' timmar? Ange timtalet från 0 till 23.'),0,[p('Klockan upprepar sig efter 24 timmar. Vi behöver därför resten modulo 24.')+eq(r'7^2=49\equiv1\pmod{24}'),p('Exponentens 61 par ger resten 1. En faktor 7 återstår.')+eq(r'7^{123}=(7^2)^{61}\cdot7\equiv7'),p('17+7 = 24, så klockan visar 00.00.')],'0 (klockan 00.00).','Undersök först resten av 7² modulo 24.',fig=clock())
add('2.724','kongruens',3,p('Vilken rest får man när '+m('14^{37}')+' divideras med 9?'),5,[p('14 har resten 5 modulo 9. Potenserna av 5 ger i tur och ordning resterna 5, 7, 8, 4, 2, 1. Perioden är 6.'),p('37 = 6·6+1. Efter sex hela perioder återstår den första resten, 5.')],'5.','Beräkna några potenser modulo 9 och leta efter en period.')
add('2.725','kongruens',4,p('Bestäm den sista siffran i talet '+m('23^{42}+17^{43}')+'.'),2,[p('För sista siffran räcker det att räkna modulo 10. Potenser av 3 slutar på 3, 9, 7, 1. Eftersom 42 ger resten 2 vid division med 4 slutar 23⁴² på 9.'),p('Potenser av 7 slutar på 7, 9, 3, 1. Eftersom 43 ger resten 3 vid division med 4 slutar 17⁴³ på 3.'),p('9+3 = 12, så summans sista siffra är 2.')],'2.','Bestäm sista siffran i varje potens för sig.')
add('3.353','partiell_integration',2,p('Bestäm alla primitiva funktioner med partiell integration.')+eq(r'f(x)=(2x-1)e^x'),'e^x*(2*x-3)+C',[p('Välj u=2x−1 och v′=eˣ. Då är u′=2 och v=eˣ.')+eq(r'\int(2x-1)e^x\,dx')+eq(r'=(2x-1)e^x-2\int e^x\,dx'),p('Integralen som återstår är eˣ. Samla termerna: (2x−1)eˣ−2eˣ = (2x−3)eˣ.')],m('F(x)=(2x-3)e^x+C')+'.','Välj polynomet som den faktor som ska deriveras.',fmt='primitiva')
add('3.354','partiell_integration',3,p('Bestäm alla primitiva funktioner med partiell integration. Funktionen är definierad för x > 0.')+eq(r'f(x)=x^3\ln x'),'x^4*ln(x)/4-x^4/16+C',[p('Välj u=ln x och v′=x³. Då är u′=1/x och v=x⁴/4.')+eq(r'\int x^3\ln x\,dx')+eq(r'=\frac{x^4\ln x}{4}-\frac14\int x^3\,dx'),p('Den sista integralen är x⁴/4. Glöm inte faktorn 1/4 framför den.')],m(r'F(x)=\frac{x^4\ln x}{4}-\frac{x^4}{16}+C')+'.','Logaritmen blir enklare när den deriveras.',fmt='primitiva')
add('3.355','partiell_integration',4,p('Bestäm alla primitiva funktioner med partiell integration.')+eq(r'f(x)=x^2\cos(2x)'),'x^2*sin(2*x)/2+x*cos(2*x)/2-sin(2*x)/4+C',[p('Välj u=x² och v′=cos(2x). Då är v=sin(2x)/2.')+eq(r'\int x^2\cos(2x)\,dx')+eq(r'=\frac{x^2\sin(2x)}2-J'),p('Här betecknar J integralen av x sin(2x). Partiell integration igen ger')+eq(r'\begin{aligned}J={}&-\frac{x\cos(2x)}2\\&+\frac12\int\cos(2x)\,dx\end{aligned}')+eq(r'=-\frac{x\cos(2x)}2+\frac{\sin(2x)}4'),p('Sätt in uttrycket för J. Minustecknet framför J ändrar båda tecknen.')],m(r'F(x)=\frac{x^2\sin(2x)}2+\frac{x\cos(2x)}2-\frac{\sin(2x)}4+C')+'.','Efter första omgången återstår en produkt med x i stället för x².',fmt='primitiva')
add('3.356','partiell_integration',5,p('Bestäm alla primitiva funktioner med partiell integration.')+eq(r'f(x)=e^{2x}\sin x'),'e^(2*x)*(2*sin(x)-cos(x))/5+C',[p('Låt I beteckna integralen av e²ˣ sin x och J integralen av e²ˣ cos x. Partiell integration ger')+eq(r'I=\frac{e^{2x}\sin x}{2}-\frac J2'),p('Gör partiell integration även i J.')+eq(r'J=\frac{e^{2x}\cos x}{2}+\frac I2'),p('Sätt in det andra sambandet i det första och samla I-termerna.')+eq(r'\frac54I=\frac{e^{2x}\sin x}{2}-\frac{e^{2x}\cos x}{4}')],m(r'F(x)=\frac{e^{2x}(2\sin x-\cos x)}5+C')+'.','Efter två partiella integrationer kommer ursprungsintegralen tillbaka.',fmt='primitiva')
add('3.357','partiell_integration',3,p('Beräkna arean av det skuggade området exakt med partiell integration. Kurvan är '+m(r'y=x\cos x')+' och gränserna är '+m('x=0')+' och '+m(r'x=\pi/2')+'.'),'pi/2-1',[p('På intervallet är x cos x ≥ 0. Arean är därför integralen mellan de givna gränserna. Välj u=x och v′=cos x.')+eq(r'F(x)=x\sin x+\cos x'),p('Sätt in gränserna.')+eq(r'A=\left(\frac\pi2\cdot1+0\right)-(0+1)')],m(r'\frac\pi2-1')+' areaenheter.','Bestäm först en primitiv funktion och använd sedan integrationsgränserna.',fmt='uttryck',fig=area())
if __name__=='__main__':
 path=ROOT/'uppgiftermatf1.js';raw=path.read_text();bank=json.loads(raw[raw.index('['):raw.rindex(']')+1]);existing={q['id'] for q in bank}
 assert not existing.intersection(q['id'] for q in TASKS),'ID finns redan: avbryt hellre än skriv över'
 index=raw.rindex(']');raw=raw[:index].rstrip()+',\n'+',\n'.join('  '+json.dumps(q,ensure_ascii=False,indent=2).replace('\n','\n  ') for q in TASKS)+'\n'+raw[index:];path.write_text(raw)
 print(len(TASKS),[q['id'] for q in TASKS])
